export const plans=[
 {id:'mimo',name:'Um Mimo',price:'14,90',description:'Fotos, voz e uma história só de vocês.',items:['1 presente digital em Stories','Suas fotos com legendas e enquadramento','Carta, áudio e detalhes interativos','Arquivo para guardar e compartilhar'],format:'stories'},
 {id:'historia',name:'Uma História',price:'24,90',description:'Mais espaço para as memórias de vocês.',items:['1 livro digital com páginas à sua escolha','Fotos, mensagens e capas por ocasião','Livro em Three.js e cartão QR','12 meses de acesso + cópia para guardar'],format:'livro'},
 {id:'celebrar',name:'Celebrar Juntos',price:'39,90',description:'Um convite para dividir um dia especial.',items:['1 convite de evento personalizado','Data, local e mensagem aos convidados','Até 100 confirmações de presença','12 meses de acesso + cartão com QR'],format:'convite'}
];
export function initCommerce({getState,onSelectPlan,onGuideFinish}){
 const section=document.createElement('section');section.className='pricing section-width';section.id='planos';section.innerHTML='<div class="section-heading"><div><h2>Preço pequeno.<br>Carinho de sobra.</h2></div><p>Pagamento único, para uma ocasião.<br>Uma proposta simples e sem assinatura.</p></div><p class="pricing-status">Proposta de lançamento para avaliação. A compra ainda não está ativa.</p><div class="pricing-grid"></div><p class="pricing-footnote">Duração e limites acima são a proposta comercial do produto. Nesta versão você pode personalizar, testar a abertura e conhecer o tutorial, sem cobrança.</p>';
 for(const plan of plans){const article=document.createElement('article');article.className='plan-card'+(plan.id==='historia'?' featured':'');article.innerHTML='<h3></h3><p class="plan-description"></p><p class="plan-price">R$ <strong></strong><span>pagamento único</span></p><ul></ul><button class="button '+(plan.id==='historia'?'primary':'outline')+'">Montar com este plano ↗</button><button class="plan-preview">Ver o fluxo de compra</button>';article.querySelector('h3').textContent=plan.name;article.querySelector('.plan-description').textContent=plan.description;article.querySelector('.plan-price strong').textContent=plan.price;plan.items.forEach(text=>{const li=document.createElement('li');li.textContent=text;article.querySelector('ul').append(li);});article.querySelector('.button').addEventListener('click',()=>openOrder(plan));article.querySelector('.plan-preview').addEventListener('click',()=>openOrder(plan));section.querySelector('.pricing-grid').append(article);}
 document.querySelector('.faq-section').before(section);
 const dialog=document.createElement('dialog');dialog.className='order-dialog';dialog.setAttribute('aria-labelledby','order-title');dialog.innerHTML='<button class="order-close" aria-label="Fechar resumo">×</button><p class="order-demo-label">Demonstração · nenhum pagamento será feito</p><h2 id="order-title">Seu próximo carinho.</h2><div class="order-summary"></div><ol class="order-flow"><li>Escolher o plano</li><li>Confirmar o pagamento com segurança</li><li>Continuar com o tutorial de criação</li><li>Conferir e preparar a entrega</li></ol><p>O checkout real será conectado ao provedor de pagamento. Por enquanto, você pode experimentar a etapa seguinte.</p><button class="button primary order-test">Testar o tutorial pós-compra</button>';document.body.append(dialog);let selected=plans[1];
 function openOrder(plan){selected=plan;const summary=dialog.querySelector('.order-summary');summary.replaceChildren();const name=document.createElement('strong');name.textContent=plan.name;const price=document.createElement('span');price.textContent='R$ '+plan.price+' · pagamento único';summary.append(name,price);dialog.showModal();}
 dialog.querySelector('.order-close').addEventListener('click',()=>dialog.close());dialog.querySelector('.order-test').addEventListener('click',()=>{dialog.close();onSelectPlan(selected);startGuide();});
 const guide=document.createElement('div');guide.className='creation-guide';guide.hidden=true;guide.innerHTML='<div class="guide-heading"><span>Vamos fazer juntos</span><button aria-label="Fechar tutorial" class="guide-close">×</button></div><progress max="4" value="1" aria-label="Progresso do tutorial"></progress><h3></h3><p></p><span class="guide-error" role="status"></span><div class="guide-actions"><button class="guide-back">Voltar</button><button class="guide-next">Continuar</button></div>';document.querySelector('.customizer').prepend(guide);
 const steps=[
 {title:'Escolha o seu jeito.',text:'Stories, livro, cartão ou convite? Escolha o formato e a ocasião. Você pode mudar depois.',target:'.format-field'},
 {title:'Nome, apelido e carinho.',text:'Escreva para quem é o presente, seu nome e, nos Stories, o apelido que vocês usam. A data especial pode aparecer no contador.',target:'#recipient'},
 {title:'Traga as lembranças.',text:'Escolha ou arraste suas fotos. Escreva legendas e use as setas para organizar. Adicione suas fotos e organize os capítulos no seu ritmo.',target:'.photo-upload'},
 {title:'Dê voz ao seu mimo.',text:'Escolha uma trilha, envie um áudio, grave sua voz ou use um link de música. Tudo é opcional. O microfone só abre quando você tocar em gravar.',target:'.audio-studio'},
 {title:'Escreva a sua carta.',text:'Pode ser uma frase ou uma história. Se precisar de ajuda para começar, use “Me dá um começo” e edite com suas próprias palavras.',target:'.letter-editor'},
 {title:'Escolha suas surpresas.',text:'Contador, céu simbólico, linha do tempo, roleta, pergunta secreta e recados de quem também ama essa pessoa. Use só o que fizer sentido.',target:'.extras-editor'},
 {title:'Deixe com a sua cara.',text:'Nos Stories, escolha composição, paleta, tipografia e enquadramento. Nas capas, experimente as novas estampas da capivara. As fotos e os textos são preservados.',target:'.materials-panel'},
 {title:'Confira e prepare a entrega.',text:'Veja pelos olhos de quem recebe. Depois guarde na biblioteca, baixe o presente e envie o arquivo. O livro, o cartão e o convite levam o 3D junto. Você pode voltar e ajustar tudo.',target:'#recipient-preview'}];let step=0;
 function renderGuide(){document.querySelectorAll('.guide-focus').forEach(e=>e.classList.remove('guide-focus'));guide.querySelector('h3').textContent=steps[step].title;guide.querySelector('p').textContent=steps[step].text;guide.querySelector('progress').max=steps.length;guide.querySelector('progress').value=step+1;guide.querySelector('.guide-next').textContent=step===steps.length-1?'Ver a surpresa':'Continuar';guide.querySelector('.guide-back').disabled=step===0;guide.querySelector('.guide-error').textContent='';document.dispatchEvent(new CustomEvent('creator:reveal',{detail:steps[step].target}));const target=document.querySelector(steps[step].target);target?.classList.add('guide-focus');if(target?.tagName==='DETAILS')target.open=true;guide.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}
 function startGuide(){step=0;guide.hidden=false;renderGuide();}
 function endGuide(){guide.hidden=true;document.querySelectorAll('.guide-focus').forEach(e=>e.classList.remove('guide-focus'));}
 guide.querySelector('.guide-close').addEventListener('click',endGuide);guide.querySelector('.guide-back').addEventListener('click',()=>{step=Math.max(0,step-1);renderGuide();});guide.querySelector('.guide-next').addEventListener('click',()=>{if(step===1&&!getState().recipient.trim()){guide.querySelector('.guide-error').textContent='Escreva para quem é o mimo para continuar.';document.querySelector('#recipient').focus();return;}if(step===steps.length-1){endGuide();onGuideFinish();return;}step++;renderGuide();});
 const help=document.createElement('button');help.className='start-tutorial';help.textContent='Precisa de uma mão? Fazer com tutorial';help.addEventListener('click',()=>{if(document.querySelector('.customizer').hidden)openOrder(plans[1]);else startGuide();});document.querySelector('.atelier-caption').after(help);
 const nav=document.querySelector('.nav-wrap nav');const link=document.createElement('a');link.href='#planos';link.textContent='Planos';nav.append(link);
 return {startGuide,openOrder(id){openOrder(typeof id==='string'?plans.find(plan=>plan.id===id)||plans[1]:id);}};
}
